import optax
from storage.praxis.synergy_model_ID897 import build_network

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'd_model': 256,
        'kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16],
        'motif_kernel_size': 5,
        'dropout_rate': 0.10,
        'reg_head_dropout': 0.05,
        'head_intermediate_dim': 128,
        'weight_decay': 0.012, # From Noema's model, which Praxis uses as base
        'grad_clip': 1.0, # From Noema's model, which Praxis uses as base
        'siamese_head_dense_dim': 64, # From Praxis's model internal
    }

def create_network(hparams):
    return build_network(d_output=hparams['d_output'], task_type=hparams['task_type'], hparams=hparams)

def create_optimizer(learning_rate: float = 0.001):
    # Praxis I's base model (from Noema II) uses weight_decay=0.012 and grad_clip=1.0
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.012)
    )
